// Define the three operations available in the application.
type Mode = 'encrypt' | 'decrypt' | 'break';

// Define the supported cipher algorithms.
type Algorithm = 'caesar' | 'vigenere' | 'rail-fence';

// Store candidate results generated by the Break operation.
type Guess = {
  key: number;
  text: string;
  score: number;
};

// Unicode contains 1,112,064 scalar values.
// Surrogate code points are excluded because they are not
// valid standalone Unicode scalar values.
const UNICODE_COUNT = 0x10f800;
const MAX_KEY = UNICODE_COUNT - 1;

// Limit the number of candidates shown in one Break operation.
const MAX_GUESSES = 5000;

// Store the display information for each algorithm.
const algorithmInfo: Record<
  Algorithm,
  { title: string; description: string }
> = {
  caesar: {
    title: 'Caesar Cipher',
    description: 'Unicode character shifting',
  },
  vigenere: {
    title: 'Vigenere Cipher',
    description: 'Polyalphabetic substitution',
  },
  'rail-fence': {
    title: 'Rail Fence Cipher',
    description: 'Zigzag transposition',
  },
};

// Convert a Unicode code point into a continuous index.
// This removes the gap occupied by UTF-16 surrogate values.
function toIndex(codePoint: number): number {
  return codePoint < 0xD800
    ? codePoint
    : codePoint - 0x800;
}

// Convert a continuous index back to a Unicode code point.
function fromIndex(index: number): number {
  return index < 0xD800
    ? index
    : index + 0x800;
}

// Shift every Unicode scalar value by the specified key.
// A negative shift performs the reverse operation.
function shiftText(text: string, shift: number): string {
  // Normalize the shift so that it stays within the valid range.
  const normalizedShift =
    ((shift % UNICODE_COUNT) + UNICODE_COUNT) %
    UNICODE_COUNT;

  // Array.from processes Unicode code points, including emoji.
  return Array.from(text, (character) => {
    const codePoint = character.codePointAt(0)!;
    const index = toIndex(codePoint);

    // Apply modular arithmetic to wrap around the Unicode range.
    const moved =
      (index + normalizedShift) % UNICODE_COUNT;

    // Convert the shifted index back into a Unicode character.
    return String.fromCodePoint(fromIndex(moved));
  }).join('');
}

// Estimate how readable a candidate plaintext looks.
// This is a simple heuristic, not a reliable language detector.
function scoreText(text: string): number {
  const characters = Array.from(text);

  if (characters.length === 0) return 0;

  let total = 0;

  for (const character of characters) {
    const cp = character.codePointAt(0)!;

    // Reward common whitespace.
    if (
      cp === 0x20 ||
      cp === 0x09 ||
      cp === 0x0a ||
      cp === 0x0d
    ) {
      total += 4;
      continue;
    }

    // Penalize control characters.
    if (cp < 0x20 || (cp >= 0x7f && cp <= 0x9f)) {
      total -= 5;
      continue;
    }

    // Reward English letters.
    if (
      (cp >= 0x41 && cp <= 0x5a) ||
      (cp >= 0x61 && cp <= 0x7a)
    ) {
      total += 5;
      continue;
    }

    // Reward Arabic letters and common Arabic character forms.
    if (
      (cp >= 0x0600 && cp <= 0x06ff) ||
      (cp >= 0x0750 && cp <= 0x077f) ||
      (cp >= 0x08a0 && cp <= 0x08ff) ||
      (cp >= 0xfb50 && cp <= 0xfdff) ||
      (cp >= 0xfe70 && cp <= 0xfeff)
    ) {
      total += 5;
      continue;
    }

    // Give digits a positive score.
    if (cp >= 0x30 && cp <= 0x39) {
      total += 3;
      continue;
    }

    // Give common punctuation a smaller positive score.
    if (
      (cp >= 0x21 && cp <= 0x2f) ||
      (cp >= 0x3a && cp <= 0x40) ||
      (cp >= 0x5b && cp <= 0x60) ||
      (cp >= 0x7b && cp <= 0x7e)
    ) {
      total += 2;
      continue;
    }

    // Keep other Unicode characters eligible for the score.
    total += 1;
  }

  // Normalize the average score to a range from 0 to 100.
  return Math.max(
    0,
    Math.min(
      100,
      Math.round((total / (characters.length * 5)) * 100)
    )
  );
}
function vigenereTransform(
  text: string,
  keyword: string,
  decrypt: boolean = false
): string {
  const cleanKey = keyword.toUpperCase();

  if (!/^[A-Z]+$/.test(cleanKey)) {
    throw new Error("The key must contain English letters A-Z only.");
  }

  let keyIndex = 0;
  let output = "";

  for (const char of text) {
    const code = char.charCodeAt(0);

    if (
      (code >= 65 && code <= 90) ||
      (code >= 97 && code <= 122)
    ) {
      const base = code >= 65 && code <= 90 ? 65 : 97;
      const textValue = code - base;
      const keyValue =
        cleanKey.charCodeAt(keyIndex % cleanKey.length) - 65;

      const result = decrypt
        ? (textValue - keyValue + 26) % 26
        : (textValue + keyValue) % 26;

      output += String.fromCharCode(result + base);
      keyIndex++;
    } else {
      output += char;
    }
  }

  return output;
}

/* Estimate the Vigenere key length using Index of Coincidence. */

/* Score English text using common letter-pair and word patterns. */
function scoreEnglishText(text: string): number {
  const normalized = text.toUpperCase();
  const lettersOnly = normalized.replace(/[^A-Z]/g, "");

  const commonWords = [
    "THE", "AND", "THAT", "HAVE", "FOR", "NOT",
    "WITH", "YOU", "THIS", "BUT", "HIS", "FROM",
    "THEY", "WERE", "BEEN", "ARE", "ING", "TION",
  ];

  const commonBigrams = [
    "TH", "HE", "IN", "ER", "AN", "RE", "ON",
    "AT", "EN", "ND", "TI", "ES", "OR", "TE",
    "OF", "ED", "IS", "IT", "AL", "AR", "ST",
    "TO", "NT", "NG", "SE", "HA", "AS", "OU",
    "IO", "LE", "VE", "CO", "ME", "DE", "HI",
  ];

  const commonTrigrams = [
    "THE", "AND", "ING", "HER", "ERE", "ENT",
    "THA", "NTH", "WAS", "ETH", "FOR", "DTH",
    "HAT", "ION", "TIO", "VER", "HIS", "OFT",
    "ITH", "FTH", "STH", "OTH", "RES", "ONT",
  ];

  let score = 0;

  for (const word of commonWords) {
    const pattern = new RegExp(`\\b${word}\\b`, "g");
    const matches = normalized.match(pattern);
    if (matches) {
      score += matches.length * (word.length >= 4 ? 8 : 5);
    }
  }

  for (let i = 0; i < lettersOnly.length - 1; i++) {
    const pair = lettersOnly.slice(i, i + 2);
    if (commonBigrams.includes(pair)) {
      score += 1;
    }
  }

  for (let i = 0; i < lettersOnly.length - 2; i++) {
    const trigram = lettersOnly.slice(i, i + 3);
    if (commonTrigrams.includes(trigram)) {
      score += 3;
    }
  }

  const vowelCount = (lettersOnly.match(/[AEIOU]/g) || []).length;
  const vowelRatio = lettersOnly.length
    ? vowelCount / lettersOnly.length
    : 0;

  if (lettersOnly.length >= 10) {
    if (vowelRatio < 0.2 || vowelRatio > 0.65) {
      score -= 5;
    }
  }

  return score;
}

function breakVigenere(text: string): string {
  // Convert the ciphertext to numbers 0-25 and ignore everything else.
  const letters: number[] = Array.from(text.toUpperCase())
    .filter((char) => char >= "A" && char <= "Z")
    .map((char) => char.charCodeAt(0) - 65);

  if (letters.length < 6) {
    return "The ciphertext is too short to analyze. Try a longer text.";
  }

  const englishFrequencies = [
    0.08167, 0.01492, 0.02782, 0.04253, 0.12702,
    0.02228, 0.02015, 0.06094, 0.06966, 0.00153,
    0.01292, 0.04025, 0.02406, 0.06749, 0.07507,
    0.01929, 0.00095, 0.05987, 0.06327, 0.09056,
    0.02758, 0.00978, 0.02360, 0.00150, 0.01974,
    0.00074,
  ];

  // Common English words: used as guessed keys AND to check if text looks English.
  const commonWords: string[] = (
    "the be to of and a in that have i it for not on with he as you do at this but his by from " +
    "they we say her she or an will my one all would there their what so up out if about who get " +
    "which go me when make can like time no just him know take people into year your good some " +
    "could them see other than then now look only come its over think also back after use two how " +
    "our work first well way even new want because any these give day most us is are was were been " +
    "has had did does am dont cant wont im thats let put keep need feel try leave call ask seem " +
    "show hear play run move live believe hold bring happen write provide sit stand lose pay meet " +
    "include continue set learn change lead understand watch follow stop create speak read allow " +
    "add spend grow open walk win offer remember love consider appear buy wait serve die send " +
    "expect build stay fall cut reach kill remain man woman child world life hand part place case " +
    "week company system program question government number night point home water room mother " +
    "area money story fact month lot right study book eye job word business issue side kind head " +
    "house service friend father power hour game line end member law car city community name " +
    "president team minute idea kid body information school people way face door art war history " +
    "party result change morning reason research girl guy moment air teacher force education " +
    "foot boy age policy music market sense nation plan college interest death experience effect " +
    "class control care field development role effort rate heart drug show leader light voice " +
    "wife police mind price report decision son view relationship town road arm difference " +
    "value building action model season society tax director position player record paper " +
    "space ground form event official matter center couple site project activity star table " +
    "need court oil situation cost industry figure street image phone data picture practice " +
    "piece land product doctor wall patient worker news test movie north love support technology " +
    "step baby computer type attention film tree source organization hair window culture " +
    "chance brother energy period course summer plant opportunity term letter condition choice " +
    "busy happy secret hello cipher crypto code key message attack dawn tonight tomorrow " +
    "today yesterday safe danger password simple answer teach listen hacker security network " +
    "python java engineer egypt cairo lemon small large great little long high old big own same " +
    "different another again never always often very much many more less too here where why " +
    "while still before between under again each both few such nothing something everything " +
    "someone everyone anyone nobody together without within against around through during " +
    "dont be careful quick brown fox jumps lazy dog attack defend enemy king queen castle " +
    "treasure hidden meeting midnight secret agent mission target signal send help please " +
    "thank thanks yes sorry welcome good bad best better fast slow hot cold red blue green black white"
  ).split(" ");

  const wordSet = new Set<string>(commonWords);
  const maxWordLength = 12;

  type Candidate = {
    key: string;
    text: string;
    score: number; // 0 to 1, how much of the text looks like English words
    length: number;
    order: number; // lower = suggested earlier
  };

  // Decrypt only the letters (numbers 0-25) with a key. Used for scoring.
  function decryptLetters(key: string): string {
    let result = "";
    for (let i = 0; i < letters.length; i++) {
      const shift = key.charCodeAt(i % key.length) - 65;
      result += String.fromCharCode(97 + ((letters[i] - shift + 26) % 26));
    }
    return result;
  }

  // How much of the text can be split into known English words (0 to 1).
  function wordScore(plain: string): number {
    const n = plain.length;
    const best: number[] = Array(n + 1).fill(0);

    for (let i = 1; i <= n; i++) {
      best[i] = best[i - 1]; // skip this letter

      for (let len = 1; len <= Math.min(maxWordLength, i); len++) {
        const word = plain.slice(i - len, i);
        if (!wordSet.has(word)) continue;

        // Long words count fully, tiny words count less (they appear by chance).
        const weight = len >= 3 ? len : len === 2 ? 1 : 0.5;
        best[i] = Math.max(best[i], best[i - len] + weight);
      }
    }

    return best[n] / n;
  }

  // If the key is a repetition of a shorter key (KEYKEY -> KEY), shorten it.
  function reduceKey(key: string): string {
    for (let period = 1; period < key.length; period++) {
      if (
        key.length % period === 0 &&
        key === key.slice(0, period).repeat(key.length / period)
      ) {
        return key.slice(0, period);
      }
    }
    return key;
  }

  // ---------- Method 1: statistical attack (good for long texts) ----------
  function statisticalKeys(): string[] {
    const maxKeyLength = Math.max(1, Math.min(16, Math.floor(letters.length / 3)));
    const beamWidth = 60;
    const shiftsPerColumn = 4;

    type PartialKey = { key: string; score: number };

    function getColumn(length: number, column: number): number[] {
      const result: number[] = [];
      for (let i = column; i < letters.length; i += length) {
        result.push(letters[i]);
      }
      return result;
    }

    // Average Index of Coincidence (English is about 0.065, random about 0.038).
    function averageIC(length: number): number {
      let total = 0;
      let used = 0;

      for (let column = 0; column < length; column++) {
        const col = getColumn(length, column);
        if (col.length < 2) continue;

        const counts: number[] = Array(26).fill(0);
        for (const value of col) counts[value]++;

        let sum = 0;
        for (const count of counts) sum += count * (count - 1);

        total += sum / (col.length * (col.length - 1));
        used++;
      }

      return used > 0 ? total / used : 0;
    }

    const icByLength: { length: number; ic: number }[] = [];
    for (let length = 1; length <= maxKeyLength; length++) {
      icByLength.push({ length, ic: averageIC(length) });
    }

    const bestIC = Math.max(...icByLength.map((entry) => entry.ic));

    const strong = icByLength
      .filter((entry) => entry.ic >= bestIC - 0.01)
      .sort((a, b) => a.length - b.length);

    const weak = icByLength
      .filter((entry) => entry.ic < bestIC - 0.01)
      .sort((a, b) => b.ic - a.ic);

    // Try the 4 most likely lengths. Multiples are kept on purpose: if a
    // smaller length was wrong, the real one is often its multiple.
    const chosenLengths: number[] = [...strong, ...weak]
      .slice(0, 4)
      .map((entry) => entry.length);

    const keys: string[] = [];

    chosenLengths.forEach((length, groupIndex) => {
      const columnOptions: { shift: number; score: number }[][] = [];

      for (let column = 0; column < length; column++) {
        const col = getColumn(length, column);
        const options: { shift: number; score: number }[] = [];

        for (let shift = 0; shift < 26; shift++) {
          const counts: number[] = Array(26).fill(0);
          for (const encrypted of col) {
            counts[(encrypted - shift + 26) % 26]++;
          }

          // Chi-squared against English letter frequencies (lower = better).
          let chi = 0;
          for (let i = 0; i < 26; i++) {
            const expected = col.length * englishFrequencies[i];
            chi += ((counts[i] - expected) ** 2) / expected;
          }

          options.push({ shift, score: chi });
        }

        options.sort((a, b) => a.score - b.score);
        columnOptions.push(options.slice(0, shiftsPerColumn));
      }

      let beam: PartialKey[] = [{ key: "", score: 0 }];

      for (const options of columnOptions) {
        const expanded: PartialKey[] = [];

        for (const partial of beam) {
          for (const option of options) {
            expanded.push({
              key: partial.key + String.fromCharCode(65 + option.shift),
              score: partial.score + option.score,
            });
          }
        }

        expanded.sort((a, b) => a.score - b.score);
        beam = expanded.slice(0, beamWidth);
      }

      // The main length gets 3 slots, the alternative lengths get 1 each.
      const slots = groupIndex === 0 ? 3 : 1;
      let taken = 0;

      for (const partial of beam) {
        if (taken >= slots) break;
        keys.push(reduceKey(partial.key));
        taken++;
      }
    });

    return keys;
  }

  // ---------- Method 2: dictionary attack (works for short texts) ----------
  function dictionaryKeys(): string[] {
    return commonWords
      .filter((word) => word.length >= 3)
      .map((word) => word.toUpperCase());
  }

  // ---------- Combine both methods ----------
  const keyOrder = new Map<string, number>();
  let order = 0;

  // The statistical method needs enough letters to be meaningful.
  if (letters.length >= 30) {
    for (const key of statisticalKeys()) {
      if (!keyOrder.has(key)) keyOrder.set(key, order++);
    }
  }

  for (const key of dictionaryKeys()) {
    const reduced = reduceKey(key);
    if (!keyOrder.has(reduced)) keyOrder.set(reduced, order++);
  }

  const candidates: Candidate[] = [];

  keyOrder.forEach((keyOrderIndex, key) => {
    candidates.push({
      key,
      text: "",
      score: wordScore(decryptLetters(key)),
      length: key.length,
      order: keyOrderIndex,
    });
  });

  candidates.sort(
    (a, b) => b.score - a.score || a.length - b.length || a.order - b.order
  );

  const top = candidates.slice(0, 5);

  for (const candidate of top) {
    candidate.text = vigenereTransform(text, candidate.key, true);
  }

  // Short texts need a higher match, because random letters can look English by chance.
  const minimumScore = letters.length < 30 ? 0.7 : 0.4;

  const warning =
    top[0].score < minimumScore
      ? "Low confidence: the key is probably not a common word, or the text is too short for statistics.\n\n"
      : "";

  return (
    warning +
    top
      .map(
        (candidate, index) =>
          `${index + 1}. Estimated Key: ${candidate.key}\n` +
          `Key Length: ${candidate.length}\n` +
          `English match: ${Math.round(candidate.score * 100)}%\n` +
          `Decrypted Text: ${candidate.text}`
      )
      .join("\n\n")
  );
}

/* Encrypt text using the Rail Fence zigzag pattern. */
function railFenceEncrypt(text: string, rails: number): string {
  if (rails < 2) {
    throw new Error("Rail depth must be at least 2.");
  }

  const rows: string[][] = Array.from(
    { length: rails },
    () => []
  );

  let row = 0;
  let direction = 1;

  for (const char of text) {
    rows[row].push(char);

    if (row === 0) {
      direction = 1;
    } else if (row === rails - 1) {
      direction = -1;
    }

    row += direction;
  }

  return rows.map((line) => line.join("")).join("");
}

/* Decrypt text using the same Rail Fence depth. */
function railFenceDecrypt(text: string, rails: number): string {
  if (rails < 2) {
    throw new Error("Rail depth must be at least 2.");
  }

  const pattern: number[] = [];
  let row = 0;
  let direction = 1;

  // Recreate the zigzag pattern for every character position.
  for (let i = 0; i < text.length; i++) {
    pattern.push(row);

    if (row === 0) {
      direction = 1;
    } else if (row === rails - 1) {
      direction = -1;
    }

    row += direction;
  }

  // Count how many characters belong to each rail.
  const counts = Array(rails).fill(0);

  for (const rail of pattern) {
    counts[rail]++;
  }

  // Split the ciphertext into the corresponding rail segments.
  const segments: string[][] = [];
  let position = 0;

  for (let rail = 0; rail < rails; rail++) {
    segments.push(
      Array.from(text.slice(position, position + counts[rail]))
    );
    position += counts[rail];
  }

  // Rebuild the original text by following the zigzag pattern.
  const offsets = Array(rails).fill(0);
  let output = "";

  for (const rail of pattern) {
    output += segments[rail][offsets[rail]];
    offsets[rail]++;
  }

  return output;
}

/* Try different rail depths to help break a Rail Fence cipher. */
function breakRailFence(text: string): string {
  const candidates: string[] = [];
  const maxRails = Math.min(text.length - 1, 10);

  for (let rails = 2; rails <= maxRails; rails++) {
    candidates.push(
      `Rails: ${rails}\nText: ${railFenceDecrypt(text, rails)}`
    );
  }

  return candidates.length > 0
    ? candidates.join("\n\n")
    : "Text is too short to test different rail depths.";
}

// Validate that the input contains a non-negative whole number.
function isNonNegativeInteger(value: string): boolean {
  return (
    /^\d+$/.test(value.trim()) &&
    Number.isSafeInteger(Number(value.trim()))
  );
}


export default function CipherScreen() {
  // Read the selected algorithm from the Expo Router URL.
  const { algorithm } = useLocalSearchParams<{
    algorithm: string;
  }>();

  // Provide navigation back to the home screen.
  const router = useRouter();

  // Track the selected operation.
  const [mode, setMode] = useState<Mode>('encrypt');

  // Store the user's input text.
  const [inputText, setInputText] = useState('');

  // Store the Caesar key or another algorithm's key.
  const [key, setKey] = useState('');

  // Store the output of encryption or decryption.
  const [result, setResult] = useState('');

  // Store validation messages and operation status.
  const [message, setMessage] = useState('');

  // Store the first and last keys to test during Caesar breaking.
  const [startKey, setStartKey] = useState('0');
  const [endKey, setEndKey] = useState('200');

  // Store all candidate plaintexts produced by Break.
  const [guesses, setGuesses] = useState<Guess[]>([]);

  // Reset the screen whenever the selected algorithm changes.
  useEffect(() => {
  setInputText('');
  setKey('');
  setResult('');
  setMessage('');
  setGuesses([]);
  setStartKey('0');
  setEndKey('200');
  setMode('encrypt');
}, [algorithm]);

  // Check that the requested algorithm is supported.
  const isValidAlgorithm =
    algorithm === 'caesar' ||
    algorithm === 'vigenere' ||
    algorithm === 'rail-fence';

  // Display a safe fallback screen for an invalid route.
  if (!isValidAlgorithm) {
    return (
      <SafeAreaView style={styles.safeArea}>
        <View style={styles.container}>
          <Text style={styles.title}>Unknown Algorithm</Text>

          <TouchableOpacity
            style={styles.primaryButton}
            onPress={() => router.replace('/')}
          >
            <Text style={styles.buttonText}>Back to Home</Text>
          </TouchableOpacity>
        </View>
      </SafeAreaView>
    );
  }

  // Retrieve the selected algorithm's title and description.
  const info = algorithmInfo[algorithm];

  // Reset previous output when the operation changes.
  function changeMode(newMode: Mode) {
    setMode(newMode);
    setResult('');
    setMessage('');
    setGuesses([]);
    setKey('');
  }

  // Execute the selected operation.
  function handleRun() {
    setResult('');
    setMessage('');
    setGuesses([]);

    // Reject empty input before processing.
    if (inputText.length === 0) {
      setMessage('Please enter some text first.');
      return;
    }

    /* Handle Vigenere operations before the Caesar implementation. */
if (algorithm === "vigenere") {
  try {
    if (mode === "break") {
      const candidates = breakVigenere(inputText);

      setResult(candidates);
      setMessage(
        "Analysis complete. These are estimated candidates; results may be inaccurate for short texts."
      );
      return;
    }

    if (!key.trim()) {
      setMessage("Enter a keyword using English letters A-Z.");
      return;
    }

    if (!/^[A-Za-z]+$/.test(key.trim())) {
      setMessage("The keyword must contain English letters A-Z only.");
      return;
    }

    const output = vigenereTransform(
      inputText,
      key.trim(),
      mode === "decrypt"
    );

    setResult(output);
    setMessage("Operation completed successfully.");
    return;
  } catch (error) {
    setMessage(
      error instanceof Error ? error.message : "An unexpected error occurred."
    );
    return;
  }
}

/* Handle Rail Fence operations without changing other ciphers. */
if (algorithm === "rail-fence") {
  try {
    if (mode === "break") {
      setResult(breakRailFence(inputText));
      setMessage(
        "Tested different rail depths. Check the candidates to find the original text."
      );
      return;
    }

    if (!/^\d+$/.test(key.trim())) {
      setMessage("Enter a valid rail depth (a whole number).");
      return;
    }

    const rails = Number(key.trim());

    if (rails < 2 || rails > inputText.length) {
      setMessage(
        `Rail depth must be between 2 and ${inputText.length}.`
      );
      return;
    }

    const output =
      mode === "encrypt"
        ? railFenceEncrypt(inputText, rails)
        : railFenceDecrypt(inputText, rails);

    setResult(output);
    setMessage("Operation completed successfully.");
    return;
  } catch (error) {
    setMessage(
      error instanceof Error ? error.message : "An unexpected error occurred."
    );
    return;
  }
}

/* Keep the existing Caesar implementation unchanged. */
if (algorithm !== "caesar") {
  setMessage("This algorithm is not implemented yet.");
  return;
}

    // Break tries a range of possible keys instead of
    // requiring the user to provide one specific key.
    if (mode === 'break') {
      if (
        !isNonNegativeInteger(startKey) ||
        !isNonNegativeInteger(endKey)
      ) {
        setMessage(
          'Start Key and End Key must be whole numbers.'
        );
        return;
      }

      const first = Number(startKey.trim());
      const last = Number(endKey.trim());

      // Validate the range and its maximum size.
      if (
        first > MAX_KEY ||
        last > MAX_KEY ||
        first > last
      ) {
        setMessage(
          `Enter keys from 0 to ${MAX_KEY}. Start must not exceed End.`
        );
        return;
      }

      if (last - first + 1 > MAX_GUESSES) {
        setMessage(
          `Choose a range containing at most ${MAX_GUESSES} keys.`
        );
        return;
      }

      const candidates: Guess[] = [];

      // Decrypt the ciphertext using each possible key.
      for (let k = first; k <= last; k++) {
        const candidateText = shiftText(inputText, -k);

        candidates.push({
          key: k,
          text: candidateText,
          score: scoreText(candidateText),
        });
      }
           
      

      // Rank candidates by readability, highest score first.
      // When scores tie, display the smaller key first.
      candidates.sort((a, b) => {
        if (b.score !== a.score) {
          return b.score - a.score;
        }

        return a.key - b.key;
      });

      setGuesses(candidates);
      setMessage(
        `Tested ${candidates.length} keys. Results are ranked by estimated readability.`
      );
      return;
    }

    // An empty Caesar key uses the default value of 3.
    if (key.trim() !== '' && !isNonNegativeInteger(key)) {
      setMessage('The key must be a non-negative whole number.');
      return;
    }

    const currentKey = key.trim() === '' ? 3 : Number(key.trim());

    // Reject keys outside the supported Unicode range.
    if (currentKey < 0 || currentKey > MAX_KEY) {
      setMessage(`The key must be between 0 and ${MAX_KEY}.`);
      return;
    }

    // Encryption shifts forward; decryption shifts backward.
    const direction = mode === 'encrypt' ? currentKey : -currentKey;

    setResult(shiftText(inputText, direction));

    setMessage(
      mode === 'encrypt'
        ? 'Encryption completed successfully.'
        : 'Decryption completed successfully.'
    );
  }

  // Copy the displayed result to the device clipboard.
  async function copyResult(text: string) {
    try {
      await Clipboard.setStringAsync(text);
      setMessage('Text copied to clipboard.');
    } catch {
      setMessage('Could not copy the text. Please try again.');
    }
  }

  // Display a selected candidate in the main result panel.
  function selectCandidate(guess: Guess) {
    setResult(guess.text);
    setMessage(`Selected candidate for key ${guess.key}.`);
  }

  // Clear all input fields and previous results.
  function clearAll() {
    setInputText('');
    setKey('');
    setResult('');
    setMessage('');
    setGuesses([]);
    setStartKey('0');
    setEndKey('200');
  }

  // Render the complete cipher interface.
  return (
    <SafeAreaView style={styles.safeArea}>
      <ScrollView
        contentContainerStyle={styles.container}
        keyboardShouldPersistTaps="handled"
      >
        {/* Return to the algorithm selection screen. */}
        <TouchableOpacity
          style={styles.backButton}
          onPress={() => router.replace('/')}
        >
          <Text style={styles.backText}>‹  Back to Home</Text>
        </TouchableOpacity>

        {/* Display the selected algorithm information. */}
        <Text style={styles.title}>{info.title}</Text>
        <Text style={styles.description}>{info.description}</Text>

        {/* Let the user select Encrypt, Decrypt, or Break. */}
        <Text style={styles.sectionTitle}>Choose an Operation</Text>

        <View style={styles.modeContainer}>
          {(
            [
              ['encrypt', 'Encrypt'],
              ['decrypt', 'Decrypt'],
              ['break', 'Break'],
            ] as [Mode, string][]
          ).map(([item, label]) => (
            <TouchableOpacity
              key={item}
              style={[
                styles.modeButton,
                mode === item && styles.activeMode,
              ]}
              onPress={() => changeMode(item)}
            >
              <Text
                style={[
                  styles.modeText,
                  mode === item && styles.activeModeText,
                ]}
              >
                {label}
              </Text>
            </TouchableOpacity>
          ))}
        </View>

        {/* Explain which text should be entered for this operation. */}
        <Text style={styles.sectionTitle}>
          {mode === 'encrypt'
            ? 'Original Text'
            : mode === 'decrypt'
              ? 'Encrypted Text'
              : 'Ciphertext to Break'}
        </Text>

        <TextInput
          style={styles.textArea}
          value={inputText}
          onChangeText={setInputText}
          placeholder="Enter Arabic, English, numbers or symbols..."
          placeholderTextColor="#8493A8"
          multiline
          textAlignVertical="top"
          autoCapitalize="none"
        />

        {/* Show key inputs for encryption and decryption. */}
        {mode !== 'break' && (
          <>
            <Text style={styles.sectionTitle}>
              {algorithm === 'vigenere'
                ? 'Keyword'
                : algorithm === 'rail-fence'
                  ? 'Rail Depth'
                  : 'Key (K)'}
            </Text>

            <TextInput
              style={styles.keyInput}
              value={key}
              onChangeText={setKey}
              placeholder={
                algorithm === 'vigenere'
                  ? 'Example: KEY'
                  : algorithm === 'rail-fence'
                    ? 'Example: 3'
                    : 'Empty = default key 3'
              }
              placeholderTextColor="#8493A8"
              autoCapitalize={
                algorithm === 'vigenere' ? 'characters' : 'none'
              }
              keyboardType={
                algorithm === 'vigenere' ? 'default' : 'number-pad'
              }
            />
          </>
        )}

        {/* Let the user specify a range of keys for Caesar Break. */}
        {mode === 'break' && algorithm === 'caesar' && (
          <View>
            <Text style={styles.sectionTitle}>Key Search Range</Text>

            <View style={styles.rangeContainer}>
              <View style={styles.rangeField}>
                <Text style={styles.label}>Start Key</Text>
                <TextInput
                  style={styles.keyInput}
                  value={startKey}
                  onChangeText={setStartKey}
                  keyboardType="number-pad"
                  placeholder="0"
                  placeholderTextColor="#8493A8"
                />
              </View>

              <View style={styles.rangeField}>
                <Text style={styles.label}>End Key</Text>
                <TextInput
                  style={styles.keyInput}
                  value={endKey}
                  onChangeText={setEndKey}
                  keyboardType="number-pad"
                  placeholder="25"
                  placeholderTextColor="#8493A8"
                />
              </View>
            </View>

            <Text style={styles.helperText}>
              Maximum {MAX_GUESSES} candidates per run.
              Results are ranked by a simple readability estimate.
            </Text>
          </View>
        )}

        {/* Execute the selected operation. */}
        <TouchableOpacity
          style={styles.primaryButton}
          onPress={handleRun}
        >
          <Text style={styles.buttonText}>
            {mode === 'encrypt'
              ? 'Encrypt Text'
              : mode === 'decrypt'
                ? 'Decrypt Text'
                : 'Break Cipher'}
          </Text>
        </TouchableOpacity>

        {/* Reset input and output fields. */}
        <TouchableOpacity
          style={styles.clearButton}
          onPress={clearAll}
        >
          <Text style={styles.clearButtonText}>Clear All</Text>
        </TouchableOpacity>

        {/* Display operation status and validation feedback. */}
        {message !== '' && (
          <Text style={styles.message}>{message}</Text>
        )}

        {/* Show the result with selectable text and a Copy button. */}
        {result !== '' && (
          <View style={styles.resultBox}>
            <View style={styles.resultHeader}>
              <Text style={styles.resultTitle}>Result</Text>

              <TouchableOpacity
                style={styles.copyButton}
                onPress={() => copyResult(result)}
              >
                <Text style={styles.copyButtonText}>Copy</Text>
              </TouchableOpacity>
            </View>

            <Text selectable style={styles.resultText}>
              {result}
            </Text>
          </View>
        )}

        {/* Display candidate plaintexts generated by Caesar Break. */}
        {guesses.length > 0 && (
          <View style={styles.resultsSection}>
            <Text style={styles.resultTitle}>
              Ranked Candidates ({guesses.length})
            </Text>

            {guesses.map((guess, index) => (
              <View key={guess.key} style={styles.candidateBox}>
                <View style={styles.candidateHeader}>
                  <View style={styles.candidateInfo}>
                    <Text style={styles.candidateKey}>
                      #{index + 1} · Key {guess.key}
                    </Text>

                    <Text style={styles.scoreText}>
                      Readability estimate: {guess.score}/100
                    </Text>
                  </View>

                  <TouchableOpacity
                    style={styles.selectButton}
                    onPress={() => selectCandidate(guess)}
                  >
                    <Text style={styles.selectButtonText}>Select</Text>
                  </TouchableOpacity>
                </View>

                {/* Allow the candidate text to be selected manually. */}
                <Text selectable style={styles.resultText}>
                  {guess.text}
                </Text>

                {/* Copy a candidate without selecting it first. */}
                <TouchableOpacity
                  style={styles.candidateCopyButton}
                  onPress={() => copyResult(guess.text)}
                >
                  <Text style={styles.copyButtonText}>Copy Candidate</Text>
                </TouchableOpacity>
              </View>
            ))}
          </View>
        )}
      </ScrollView>
    </SafeAreaView>
  );
}

